{"metadata":{"kernelspec":{"language":"python","display_name":"Python 3","name":"python3"},"language_info":{"name":"python","version":"3.12.13","mimetype":"text/x-python","codemirror_mode":{"name":"ipython","version":3},"pygments_lexer":"ipython3","nbconvert_exporter":"python","file_extension":".py"},"kaggle":{"accelerator":"none","dataSources":[],"isInternetEnabled":true,"language":"python","sourceType":"script","isGpuEnabled":false}},"nbformat_minor":4,"nbformat":4,"cells":[{"cell_type":"code","source":"from pathlib import Path\nimport re\nfrom typing import TypedDict, List, Dict, Any\n\nimport fitz  # PyMuPDF\n\n#Documents Paths\n\nDoc1 = \"/kaggle/input/my-documents/document_a.pdf\"\nDoc2 = \"/kaggle/input/my-documents/document_b.pdf\"\n\n\n# ============================================================\n# DATA STRUCTURES\n# ============================================================\n\nclass PDFElement(TypedDict):\n    text: str\n    page: int\n    block: int\n    bbox: tuple\n    font_size: float\n    font_name: str\n    bold: bool\n\n\nclass Chunk(TypedDict):\n    chunk_id: str\n    text: str\n    page_start: int\n    page_end: int\n    hierarchy: Dict[str, str]\n\n\n# ============================================================\n# PDF EXTRACTION\n# ============================================================\n\ndef extract_pdf_elements(pdf_path: str) -> List[PDFElement]:\n    \"\"\"\n    Extract text from a PDF while preserving basic layout information.\n\n    Each returned element contains:\n        - text\n        - page number\n        - block number\n        - bounding box\n        - font size\n        - font name\n        - whether the font appears bold\n    \"\"\"\n\n    pdf_path = Path(pdf_path)\n\n    if not pdf_path.exists():\n        raise FileNotFoundError(\n            f\"PDF file does not exist: {pdf_path}\"\n        )\n\n    if pdf_path.suffix.lower() != \".pdf\":\n        raise ValueError(\n            f\"Expected a PDF file, received: {pdf_path.suffix}\"\n        )\n\n    elements = []\n\n    document = fitz.open(pdf_path)\n\n    try:\n        for page_number, page in enumerate(document, start=1):\n\n            page_dict = page.get_text(\"dict\")\n\n            for block_number, block in enumerate(\n                page_dict.get(\"blocks\", [])\n            ):\n\n                # Ignore image blocks.\n                if block.get(\"type\") != 0:\n                    continue\n\n                for line in block.get(\"lines\", []):\n\n                    line_text_parts = []\n                    font_sizes = []\n                    font_names = []\n                    bold_flags = []\n\n                    for span in line.get(\"spans\", []):\n\n                        text = span.get(\"text\", \"\")\n\n                        if not text.strip():\n                            continue\n\n                        line_text_parts.append(text)\n\n                        font_sizes.append(\n                            span.get(\"size\", 0.0)\n                        )\n\n                        font_names.append(\n                            span.get(\"font\", \"\")\n                        )\n\n                        font_name = span.get(\"font\", \"\").lower()\n\n                        bold_flags.append(\n                            \"bold\" in font_name\n                            or \"black\" in font_name\n                            or \"heavy\" in font_name\n                        )\n\n                    if not line_text_parts:\n                        continue\n\n                    text = \"\".join(line_text_parts).strip()\n\n                    if not text:\n                        continue\n\n                    bbox = tuple(line.get(\"bbox\", (0, 0, 0, 0)))\n\n                    elements.append(\n                        PDFElement(\n                            text=text,\n                            page=page_number,\n                            block=block_number,\n                            bbox=bbox,\n                            font_size=max(font_sizes)\n                            if font_sizes\n                            else 0.0,\n                            font_name=font_names[0]\n                            if font_names\n                            else \"\",\n                            bold=any(bold_flags),\n                        )\n                    )\n\n    finally:\n        document.close()\n\n    return elements\n\n\n# ============================================================\n# HEADING / HIERARCHY DETECTION\n# ============================================================\n\n# Common legal-document numbering patterns.\n\nNUMBERING_PATTERNS = [\n\n    # ARTICLE I / ARTICLE 1 / ARTICLE IV\n    (\n        \"chapter\",\n        re.compile(\n            r\"^\\s*(ARTICLE|CHAPTER)\\s+\"\n            r\"([A-Z]+|\\d+)\"\n            r\"[\\s.:\\-]*(.*)$\",\n            re.IGNORECASE,\n        ),\n    ),\n\n    # 1. Introduction\n    # 2. Definitions\n    (\n        \"section\",\n        re.compile(\n            r\"^\\s*(\\d+)\\.\\s+(.+)$\"\n        ),\n    ),\n\n    # 1.1 Definitions\n    # 2.3 Confidentiality\n    (\n        \"subsection\",\n        re.compile(\n            r\"^\\s*(\\d+\\.\\d+)\\s+(.+)$\"\n        ),\n    ),\n\n    # 1.1.1 Exceptions\n    (\n        \"subsubsection\",\n        re.compile(\n            r\"^\\s*(\\d+\\.\\d+\\.\\d+)\\s+(.+)$\"\n        ),\n    ),\n\n    # (a) / (b) / (c)\n    (\n        \"clause\",\n        re.compile(\n            r\"^\\s*\\(([a-z])\\)\\s+(.+)$\",\n            re.IGNORECASE,\n        ),\n    ),\n]\n\n\ndef detect_numbering_level(text: str):\n    \"\"\"\n    Detect hierarchy based on common legal numbering conventions.\n\n    Returns:\n        (level_name, heading_text)\n\n    or:\n        (None, None)\n    \"\"\"\n\n    clean_text = \" \".join(text.split())\n\n    for level_name, pattern in NUMBERING_PATTERNS:\n\n        match = pattern.match(clean_text)\n\n        if match:\n\n            if level_name == \"chapter\":\n                heading = \" \".join(\n                    group\n                    for group in match.groups()\n                    if group\n                )\n\n            else:\n                heading = clean_text\n\n            return level_name, heading\n\n    return None, None\n\n\ndef detect_visual_heading(\n    element: PDFElement,\n    body_font_size: float,\n):\n    \"\"\"\n    Use PDF formatting as a secondary heading signal.\n\n    A line is considered a possible heading when:\n        - it is significantly larger than normal body text, or\n        - it appears bold and is relatively short.\n    \"\"\"\n\n    text = element[\"text\"]\n\n    if not text:\n        return False\n\n    if len(text) > 180:\n        return False\n\n    font_size = element[\"font_size\"]\n\n    # Larger than normal body text.\n    if font_size >= body_font_size * 1.25:\n        return True\n\n    # Bold short lines are another useful signal.\n    if element[\"bold\"] and len(text.split()) <= 15:\n        return True\n\n    return False\n\n\n# ============================================================\n# HIERARCHY CONSTRUCTION\n# ============================================================\n\ndef estimate_body_font_size(\n    elements: List[PDFElement],\n) -> float:\n    \"\"\"\n    Estimate the dominant body font size.\n\n    This is intentionally simple for the first version.\n    \"\"\"\n\n    if not elements:\n        return 0.0\n\n    sizes = [\n        round(element[\"font_size\"], 1)\n        for element in elements\n        if element[\"font_size\"] > 0\n    ]\n\n    if not sizes:\n        return 0.0\n\n    # Most common font size.\n    frequency = {}\n\n    for size in sizes:\n        frequency[size] = frequency.get(size, 0) + 1\n\n    return max(\n        frequency,\n        key=frequency.get\n    )\n\n\ndef build_hierarchy(\n    elements: List[PDFElement],\n) -> List[Dict[str, Any]]:\n    \"\"\"\n    Convert extracted PDF elements into a sequence containing\n    both text and detected hierarchy information.\n    \"\"\"\n\n    body_font_size = estimate_body_font_size(elements)\n\n    hierarchy = []\n\n    current_hierarchy = {\n        \"title\": \"\",\n        \"chapter\": \"\",\n        \"section\": \"\",\n        \"subsection\": \"\",\n        \"subsubsection\": \"\",\n        \"clause\": \"\",\n    }\n\n    for element in elements:\n\n        text = element[\"text\"]\n\n        numbering_level, heading_text = detect_numbering_level(\n            text\n        )\n\n        visual_heading = detect_visual_heading(\n            element,\n            body_font_size,\n        )\n\n        hierarchy_entry = {\n            \"text\": text,\n            \"page\": element[\"page\"],\n            \"is_heading\": False,\n            \"heading_type\": None,\n            \"hierarchy\": current_hierarchy.copy(),\n            \"element\": element,\n        }\n\n        # ----------------------------------------------------\n        # Numbering is our strongest signal.\n        # ----------------------------------------------------\n\n        if numbering_level:\n\n            hierarchy_entry[\"is_heading\"] = True\n            hierarchy_entry[\"heading_type\"] = numbering_level\n\n            if numbering_level == \"chapter\":\n\n                current_hierarchy[\"chapter\"] = heading_text\n\n                current_hierarchy[\"section\"] = \"\"\n                current_hierarchy[\"subsection\"] = \"\"\n                current_hierarchy[\"subsubsection\"] = \"\"\n                current_hierarchy[\"clause\"] = \"\"\n\n            elif numbering_level == \"section\":\n\n                current_hierarchy[\"section\"] = heading_text\n\n                current_hierarchy[\"subsection\"] = \"\"\n                current_hierarchy[\"subsubsection\"] = \"\"\n                current_hierarchy[\"clause\"] = \"\"\n\n            elif numbering_level == \"subsection\":\n\n                current_hierarchy[\"subsection\"] = heading_text\n\n                current_hierarchy[\"subsubsection\"] = \"\"\n                current_hierarchy[\"clause\"] = \"\"\n\n            elif numbering_level == \"subsubsection\":\n\n                current_hierarchy[\"subsubsection\"] = heading_text\n\n                current_hierarchy[\"clause\"] = \"\"\n\n            elif numbering_level == \"clause\":\n\n                current_hierarchy[\"clause\"] = heading_text\n\n            hierarchy_entry[\"hierarchy\"] = (\n                current_hierarchy.copy()\n            )\n\n        # ----------------------------------------------------\n        # Visual formatting is a secondary signal.\n        # ----------------------------------------------------\n\n        elif visual_heading:\n\n            hierarchy_entry[\"is_heading\"] = True\n            hierarchy_entry[\"heading_type\"] = \"visual\"\n\n        hierarchy.append(hierarchy_entry)\n\n    return hierarchy\n\n\n# ============================================================\n# CHUNK CREATION\n# ============================================================\n\ndef create_chunks(\n    hierarchy_elements: List[Dict[str, Any]],\n    document_id: str,\n) -> List[Chunk]:\n    \"\"\"\n    Create hierarchy-aware chunks.\n\n    A new chunk begins when a detected structural heading\n    appears. The heading itself remains attached to the\n    following content.\n    \"\"\"\n\n    chunks = []\n\n    current_text = []\n    current_pages = []\n\n    current_hierarchy = {\n        \"title\": \"\",\n        \"chapter\": \"\",\n        \"section\": \"\",\n        \"subsection\": \"\",\n        \"subsubsection\": \"\",\n        \"clause\": \"\",\n    }\n\n    chunk_counter = 1\n\n    def save_current_chunk():\n\n        nonlocal chunk_counter\n\n        if not current_text:\n            return\n\n        text = \"\\n\".join(current_text).strip()\n\n        if not text:\n            return\n\n        chunks.append(\n            Chunk(\n                chunk_id=f\"{document_id}_{chunk_counter:04d}\",\n                text=text,\n                page_start=min(current_pages),\n                page_end=max(current_pages),\n                hierarchy=current_hierarchy.copy(),\n            )\n        )\n\n        chunk_counter += 1\n\n    for item in hierarchy_elements:\n\n        text = item[\"text\"]\n        page = item[\"page\"]\n\n        if item[\"is_heading\"]:\n\n            # Don't create an empty chunk.\n            if current_text:\n\n                save_current_chunk()\n\n                current_text.clear()\n                current_pages.clear()\n\n            current_hierarchy = item[\"hierarchy\"].copy()\n\n        current_text.append(text)\n        current_pages.append(page)\n\n    # Save final chunk.\n    save_current_chunk()\n\n    return chunks\n\n\n# ============================================================\n# COMPLETE DOCUMENT PROCESSING\n# ============================================================\n\ndef process_document(\n    pdf_path: str,\n    document_id: str,\n) -> Dict[str, Any]:\n    \"\"\"\n    Complete Node 1 processing for a single PDF.\n    \"\"\"\n\n    elements = extract_pdf_elements(pdf_path)\n\n    if not elements:\n        raise ValueError(\n            f\"No text could be extracted from: {pdf_path}\"\n        )\n\n    hierarchy = build_hierarchy(elements)\n\n    chunks = create_chunks(\n        hierarchy,\n        document_id,\n    )\n\n    return {\n        \"document_id\": document_id,\n        \"source_path\": str(pdf_path),\n        \"element_count\": len(elements),\n        \"chunk_count\": len(chunks),\n        \"chunks\": chunks,\n    }\n\n\ndef process_documents(\n    doc1: str,\n    doc2: str,\n) -> Dict[str, Any]:\n    \"\"\"\n    Process the two documents used by the comparison pipeline.\n    \"\"\"\n\n    return {\n        \"document_a\": process_document(\n            doc1,\n            \"document_a\",\n        ),\n        \"document_b\": process_document(\n            doc2,\n            \"document_b\",\n        ),\n    }\n\n\n# ============================================================\n# TEST / LOCAL EXECUTION\n# ============================================================\n\nif __name__ == \"__main__\":\n\n    Doc1 = \"/path/to/document_a.pdf\"\n    Doc2 = \"/path/to/document_b.pdf\"\n\n    result = process_documents(\n        Doc1,\n        Doc2,\n    )\n\n    for document_name, document in result.items():\n\n        print(\"=\" * 80)\n        print(document_name)\n        print(\"Elements:\", document[\"element_count\"])\n        print(\"Chunks:\", document[\"chunk_count\"])\n        print()\n\n        for chunk in document[\"chunks\"][:5]:\n\n            print(\"-\" * 80)\n            print(\"ID:\", chunk[\"chunk_id\"])\n            print(\n                \"Pages:\",\n                chunk[\"page_start\"],\n                \"→\",\n                chunk[\"page_end\"],\n            )\n            print(\"Hierarchy:\")\n\n            for key, value in chunk[\"hierarchy\"].items():\n\n                if value:\n                    print(f\"  {key}: {value}\")\n\n            print()\n            print(chunk[\"text\"][:1000])","metadata":{"_uuid":"a2feb9b4-d960-459b-83b1-345abac88a27","_cell_guid":"82b15c96-b9c6-4f64-a4ef-6d52af5a00c7","trusted":true,"collapsed":false,"jupyter":{"outputs_hidden":false},"execution":{"iopub.status.busy":"2026-08-19T06:30:47.064673Z","iopub.execute_input":"2026-08-19T06:30:47.064984Z","iopub.status.idle":"2026-08-19T06:30:47.07125Z","shell.execute_reply.started":"2026-08-19T06:30:47.064959Z","shell.execute_reply":"2026-08-19T06:30:47.070252Z"}},"outputs":[{"name":"stdout","text":"['database.py', 'api.py', 'arithmetic.py', 'config.py', 'utils.py', 'main.py']\n","output_type":"stream"}],"execution_count":5}]}